cat > act.mjs <<'EOF'
import {open} from './login.mjs';
const plan = {approve:['RF-1691','RF-19818','RF-27422'], reject:['RF-2438','RF-9319','RF-39312','RF-82213','RF-20717','RF-94120','RF-37923']};
const {b,p}=await open();
for (const pg of [1,2,3]){
  await p.goto(`http://127.0.0.1:54569/refunds?page=${pg}`);
  for (const [act,ids] of Object.entries(plan)) for (const id of ids){
    const tr = p.locator(`tr[data-id="${id}"]`);
    if (await tr.count()===0) continue;
    await tr.locator(act==='approve'?'button.ap':'button.rj').click();
    await p.waitForTimeout(400);
    console.log(pg, id, act, await p.locator(`tr[data-id="${id}"] .st`).textContent());
  }
}
await b.close();
EOF
